<?php
/** Administrative workspace panels use AppLayout and existing vp-* components. */
use App\Core\Auth;
use App\Services\SocWorkspaceService;
use App\Core\Database;
use App\Views\Layout\AppLayout;

$service=new SocWorkspaceService();$actor=(int)$currentUser['id'];$service->requireAdmin($actor);
$h=static fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$filters=array_intersect_key($_GET,array_flip(['student_id','ticket_id','status']));
$error='';$records=[];$detail=null;
try{
    $resource=match($socPage){'StudentWorkspaces'=>'notebooks','ModelManagement'=>'models','ValidationReports'=>'validations','DeploymentRequests'=>'requests'};
    $records=$service->listResources($resource,$filters,$actor);
    if($socPage==='StudentWorkspaces'){
        $experiments=$service->listResources('experiments',$filters,$actor);$runs=$service->listResources('runs',$filters,$actor);$jobs=$service->listResources('jobs',$filters,$actor);
        if(!empty($_GET['notebook_id']))$detail=$service->notebook((int)$_GET['notebook_id'],$actor);
        if(!empty($_GET['experiment_id']))$experimentDetail=$service->experiment((int)$_GET['experiment_id'],$actor);
        if(!empty($_GET['job_id']))$jobDetail=$service->job((string)$_GET['job_id'],$actor);
    }elseif($socPage==='ModelManagement'&&!empty($_GET['id']))$detail=$service->model((int)$_GET['id'],$actor);
    elseif($socPage==='ValidationReports'&&!empty($_GET['id']))$detail=$service->validation((int)$_GET['id'],$actor);
}catch(Throwable $e){http_response_code(422);$error=$e->getMessage();}
$titles=['StudentWorkspaces'=>'Student Workspace Inspection','ModelManagement'=>'Model Management','ValidationReports'=>'Validation Reports','DeploymentRequests'=>'Deployment Requests'];
?>
<div class="flex flex-col gap-6">
    <section class="vp-card">
        <div class="vp-card-header"><h1 class="text-2xl font-bold text-primary"><?= $h($titles[$socPage]) ?></h1><span class="vp-badge">SYS-AI-05</span></div>
        <p class="text-sm text-slate-500">Inspect the original student-owned MySQL records. Administrative actions identify the administrator and preserve original student work.</p>
        <form method="get" class="flex flex-col sm:flex-row gap-3 items-end">
            <label class="text-sm">Student ID<input class="vp-input" name="student_id" type="number" min="1" value="<?= $h($filters['student_id']??'') ?>" placeholder="All students"></label>
            <label class="text-sm">Ticket ID<input class="vp-input" name="ticket_id" type="number" min="1" value="<?= $h($filters['ticket_id']??'') ?>" placeholder="All tickets"></label>
            <label class="text-sm">Record status<input class="vp-input" name="status" value="<?= $h($filters['status']??'') ?>" placeholder="All states"></label>
            <button class="vp-btn vp-btn-primary">Apply filters</button><a class="vp-btn vp-btn-secondary" href="<?= $h($socPage) ?>.php">Clear</a>
        </form>
        <p class="text-xs text-slate-500">At most 100 latest matching records are shown per table. Use filters for targeted inspection.</p>
    </section>
    <?php if($error):?><div role="alert" class="vp-card text-red-700"><?= $h($error) ?></div><?php endif;?>
    <?php if($socPage==='StudentWorkspaces'):?>
    <section class="vp-card"><h2 class="vp-card-title">Student Notebooks</h2><div class="vp-table-container"><table class="vp-table"><thead><tr><th>Notebook</th><th>Original student</th><th>Ticket</th><th>Saved state</th><th>Cells</th><th>Inspect</th></tr></thead><tbody>
        <?php if(!$records):?><tr><td colspan="6">No notebooks</td></tr><?php endif;?>
        <?php foreach($records as $r):?><tr><td><?= $h($r['code'].' · '.$r['title']) ?></td><td><?= $h($r['student_identifier'].' · '.$r['student_name']) ?></td><td><?= $h($r['ticket_code']??'No linked ticket') ?></td><td><?= $h($r['status']) ?></td><td><?= (int)$r['cells_count'] ?></td><td><a class="text-primary underline" href="?notebook_id=<?= (int)$r['id'] ?>">Read cells</a></td></tr><?php endforeach;?>
    </tbody></table></div></section>
    <?php if($detail):?><section class="vp-card"><h2 class="vp-card-title"><?= $h($detail['title']) ?> — read-only notebook</h2><p class="text-sm">Owner: <?= $h($detail['student_name']) ?> · Student ID <?= (int)$detail['student_id'] ?> · Ticket <?= $h($detail['ticket_code']??'None') ?> · Version <?= (int)$detail['version'] ?></p><?php if(!$detail['cells']):?><p>No saved cells</p><?php endif;?><?php foreach($detail['cells'] as $cell):?><article class="vp-card"><strong><?= $h($cell['cell_type']) ?> · cell <?= (int)$cell['cell_order'] ?></strong><pre class="text-xs font-mono whitespace-pre-wrap break-all"><?= $h($cell['source']) ?></pre><p class="text-xs text-slate-500">Original source preserved. No administrator edit or impersonation.</p></article><?php endforeach;?></section><?php endif;?>
    <section class="vp-card"><h2 class="vp-card-title">Student Experiments</h2><div class="vp-table-container"><table class="vp-table"><thead><tr><th>Experiment</th><th>Student</th><th>Ticket</th><th>Runs</th><th>Inspect</th></tr></thead><tbody><?php if(!$experiments):?><tr><td colspan="5">No experiments</td></tr><?php endif;?><?php foreach($experiments as $r):?><tr><td><?= $h($r['code'].' · '.$r['name']) ?></td><td><?= $h($r['student_identifier']) ?></td><td><?= $h($r['ticket_code']) ?></td><td><?= (int)$r['runs_count'] ?></td><td><a class="text-primary underline" href="?experiment_id=<?= (int)$r['id'] ?>">Inspect</a></td></tr><?php endforeach;?></tbody></table></div></section>
    <?php if(isset($experimentDetail)):?><section class="vp-card"><h2 class="vp-card-title"><?= $h($experimentDetail['name']) ?> — original experiment</h2><pre class="text-xs font-mono whitespace-pre-wrap break-all"><?= $h(json_encode($experimentDetail,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre></section><?php endif;?>
    <section class="vp-card"><h2 class="vp-card-title">Recorded Runs</h2><p class="text-xs text-slate-500">RECORDED means user-reported metadata. It does not mean Python executed or that quality was verified.</p><div class="vp-table-container"><table class="vp-table"><thead><tr><th>Run</th><th>Student</th><th>Experiment</th><th>State</th><th>User-reported parameters / metrics</th></tr></thead><tbody><?php if(!$runs):?><tr><td colspan="5">No experiment runs</td></tr><?php endif;?><?php foreach($runs as $r):?><tr><td><?= $h($r['run_uuid'].' · '.$r['run_name']) ?></td><td><?= $h($r['student_identifier']) ?></td><td><?= $h($r['experiment_code']) ?></td><td><?= $h($r['status']) ?></td><td><pre class="text-xs whitespace-pre-wrap break-all"><?= $h($r['parameters']) ?><?= "\n" ?><?= $h($r['metrics']) ?></pre></td></tr><?php endforeach;?></tbody></table></div></section>
    <section class="vp-card"><h2 class="vp-card-title">Execution Job History</h2><p class="text-sm text-slate-500">Execution UNAVAILABLE: no verified isolated runner is configured. Cancelling changes queue state; no runtime termination is claimed.</p><div class="vp-table-container"><table class="vp-table"><thead><tr><th>Job</th><th>Student</th><th>Notebook</th><th>State</th><th>Actions</th></tr></thead><tbody><?php if(!$jobs):?><tr><td colspan="5">No execution jobs</td></tr><?php endif;?><?php foreach($jobs as $r):?><tr><td><?= $h($r['job_uuid']) ?></td><td><?= $h($r['student_identifier']) ?></td><td><?= $h($r['notebook_title']) ?></td><td><?= $h($r['status']) ?></td><td><a class="text-primary underline" href="?job_id=<?= $h($r['job_uuid']) ?>">Inspect</a><?php if(in_array($r['status'],['QUEUED','RUNNING'],true)):?><form method="post" data-soc-api="soc/execution-jobs/<?= $h($r['job_uuid']) ?>/cancel" class="mt-2"><button class="vp-btn vp-btn-secondary" type="submit">Cancel queue state</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
    <?php if(isset($jobDetail)):?><section class="vp-card"><h2 class="vp-card-title">Original execution record</h2><pre class="text-xs font-mono whitespace-pre-wrap break-all"><?= $h(json_encode($jobDetail,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre></section><?php endif;?>
    <?php elseif($socPage==='ModelManagement'):?>
    <section class="vp-card"><h2 class="vp-card-title">Student Model Records</h2><div class="vp-table-container"><table class="vp-table"><thead><tr><th>Original model</th><th>Student</th><th>Ticket</th><th>Framework</th><th>Versions</th><th>Record status</th><th>Inspect</th></tr></thead><tbody><?php if(!$records):?><tr><td colspan="7">No models</td></tr><?php endif;?><?php foreach($records as $r):?><tr><td><?= $h($r['model_code'].' · '.$r['name']) ?></td><td><?= $h($r['student_identifier'].' · '.$r['student_name']) ?></td><td><?= $h($r['ticket_code']) ?></td><td><?= $h($r['framework']) ?></td><td><?= (int)$r['versions_count'] ?></td><td><?= $h($r['status']) ?></td><td><a class="text-primary underline" href="?id=<?= (int)$r['id'] ?>">Manage / versions</a></td></tr><?php endforeach;?></tbody></table></div></section>
    <?php if($detail):$adminMeta=json_decode($detail['admin_metadata_json']??'{}',true)?:[];?>
    <div class="grid grid-cols-1 xl:grid-cols-2 gap-6">
        <section class="vp-card"><h2 class="vp-card-title">Original Student Metadata</h2><p><?= $h($detail['model_code'].' · '.$detail['name']) ?></p><p class="text-sm"><?= $h($detail['description']) ?></p><p class="text-sm">Student <?= $h($detail['student_name']) ?> · Ticket <?= $h($detail['ticket_code']??'None') ?> · Student ID <?= (int)$detail['student_id'] ?></p><pre class="text-xs whitespace-pre-wrap break-all"><?= $h($detail['metadata_json']) ?></pre><p class="text-xs text-slate-500">Original student-authored fields and uploaded files remain unchanged.</p></section>
        <section class="vp-card"><h2 class="vp-card-title">Administrative Annotations</h2><form method="post" data-soc-api="soc/models/<?= (int)$detail['id'] ?>" data-soc-method="PATCH" class="flex flex-col gap-3"><label>Administrative label<input class="vp-input" name="admin_label" maxlength="255" value="<?= $h($adminMeta['admin_label']??'') ?>"></label><label>Administrative notes<textarea class="vp-input" name="admin_notes" maxlength="10000" rows="4"><?= $h($adminMeta['admin_notes']??'') ?></textarea></label><button class="vp-btn vp-btn-primary">Save administrative annotations</button></form><form method="post" data-soc-api="soc/models/<?= (int)$detail['id'] ?>" data-soc-method="PATCH"><input type="hidden" name="status" value="<?= $detail['status']==='ARCHIVED'?'REGISTERED':'ARCHIVED' ?>"><button class="vp-btn vp-btn-secondary"><?= $detail['status']==='ARCHIVED'?'Restore registration':'Archive record' ?></button></form><p class="text-xs text-slate-500">This cannot create quality evidence, inference output or a deployed endpoint.</p></section>
    </div>
    <section class="vp-card"><h2 class="vp-card-title">Immutable Artifact Versions</h2><div class="vp-table-container"><table class="vp-table"><thead><tr><th>Version</th><th>Format</th><th>Bytes</th><th>SHA-256</th><th>User-reported metrics</th></tr></thead><tbody><?php if(!$detail['versions']):?><tr><td colspan="5">No uploaded artifact versions. Metadata registration creates no file.</td></tr><?php endif;?><?php foreach($detail['versions'] as $v):?><tr><td><?= $h($v['version']) ?></td><td><?= $h($v['artifact_format']) ?></td><td><?= (int)$v['file_size'] ?></td><td class="font-mono text-xs break-all"><?= $h($v['checksum_sha256']) ?></td><td class="font-mono text-xs break-all"><?= $h($v['metrics']) ?></td></tr><?php endforeach;?></tbody></table></div></section>
    <?php endif;?>
    <?php elseif($socPage==='ValidationReports'):?>
    <section class="vp-card"><h2 class="vp-card-title">Persisted Validation Evidence</h2><p class="text-sm text-slate-500">Artifact integrity, student-supplied metrics, trusted quality evidence and administrative approval are separate. Trusted evaluation provider: NOT CONFIGURED.</p><div class="vp-table-container"><table class="vp-table"><thead><tr><th>Model/version</th><th>Student</th><th>State</th><th>Quality score</th><th>Inspect</th></tr></thead><tbody><?php if(!$records):?><tr><td colspan="5">No validation reports</td></tr><?php endif;?><?php foreach($records as $r):?><tr><td><?= $h($r['model_code'].' · '.$r['model_version']) ?></td><td><?= $h($r['student_identifier']) ?></td><td><?= $h($r['status']) ?></td><td><?= $r['score']===null?'NOT EVALUATED':$h($r['score']) ?></td><td><a class="text-primary underline" href="?id=<?= (int)$r['id'] ?>">Read evidence</a></td></tr><?php endforeach;?></tbody></table></div></section>
    <?php if($detail):?><section class="vp-card"><h2 class="vp-card-title">Report #<?= (int)$detail['id'] ?></h2><pre class="text-xs font-mono whitespace-pre-wrap break-all"><?= $h(json_encode(json_decode($detail['report_json'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre></section><?php endif;?>
    <?php elseif($socPage==='DeploymentRequests'):?>
    <section class="vp-card"><h2 class="vp-card-title">Administrative Deployment Requests</h2><p class="text-sm text-slate-500">Inference provider NOT CONFIGURED. Approval records an administrative decision; it does not deploy, validate quality, expose an endpoint or run student artifacts.</p><div class="vp-table-container"><table class="vp-table"><thead><tr><th>Request/model</th><th>Student</th><th>Environment</th><th>Decision</th><th>Runtime/provider</th><th>Review</th></tr></thead><tbody><?php if(!$records):?><tr><td colspan="6">No deployment requests</td></tr><?php endif;?><?php foreach($records as $r):?><tr><td>#<?= (int)$r['id'] ?> · <?= $h($r['model_code'].' · '.$r['model_version']) ?></td><td><?= $h($r['student_identifier']) ?></td><td><?= $h($r['environment']) ?></td><td><?= $h($r['status']) ?><p class="text-xs"><?= $h($r['decision_notes']) ?></p></td><td><?= $h($r['provider_state']) ?> · UNAVAILABLE</td><td><?php if($r['status']==='PENDING'):?><form method="post" data-soc-api="soc/deployment-requests/<?= (int)$r['id'] ?>" data-soc-method="PATCH" class="flex flex-col gap-2"><label>Decision<select class="vp-select" name="status"><option value="APPROVED">Approve request only</option><option value="REJECTED">Reject request</option></select></label><label>Notes<textarea class="vp-input" name="notes" maxlength="10000"></textarea></label><button class="vp-btn vp-btn-primary">Record decision</button></form><?php else:?>Reviewed; no runtime endpoint created<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
